function ActivityCrisisContractRankCell:Awake()
    SetButtonAction(self.Btn_Detail, Bind(self, self.OnDetailBtnClicked))
    if IsNull(self.LB_PlayerHead.Env) then
        self.LB_PlayerHead:Init()
        self.LB_PlayerHead.Env:SetCallBack(function()
            if self.data.playerId > 0 then  -- 机器人不能点
                -- 直接进入个人信息界面2D版
                GameUtils.ShowPlayerInfo(self.data.playerId)
            end
        end)
    end
end

function ActivityCrisisContractRankCell:Start()
end

