------------ lifeCycle ------------


function ActivityCrisisContractRankCell:CleanProperties()
    self.comp = nil
    self.data = nil
end

function ActivityCrisisContractRankCell:SetComponent(comp)
    self.comp = comp
end

function ActivityCrisisContractRankCell:OnDetailBtnClicked()
    -- print("[大乱斗] 排行榜详情", table.dump(self.data.team, nil, 5))
    GameUtils.ShowCommonTeamsTipsBoard(self.Btn_Detail, self.data.team, nil, nil, self.data.name)
end

function ActivityCrisisContractRankCell:Refresh(data)
    if isNull(data) then
        return
    end
    -- print("[大乱斗] cell", table.dump(data, nil, 3))
    self.data = data
    local rank = data.ranking
    local percentageRank = checkNumber(data.percentageRank)
    local playerName = data.name
    local avatarId = checkInt(data.avatar)
    local avatarFrameId = checkInt(data.avatarFrame)
    local level = data.level
    local combatValue = checkNumber(data.score)
    local isMyself = checkNumber(data.playerId) == GameUtils.GetPlayerId()

    KTool.SetActive(self.RT_MySelf, isMyself)

    local isNoRank = isNull(rank) or rank == 0
    KTool.SetActive(self.RT_NoRank, isNoRank)
    if isNoRank then
        KTool.SetActive(self.RT_NoRank, true)
        KTool.SetActive(self.Txt_RankPercentage, false)
        KTool.SetActive(self.Txt_Rank, false)
    else
        local isPercentage = percentageRank > 0
        KTool.SetActive(self.Txt_RankPercentage, isPercentage)
        KTool.SetActive(self.Txt_Rank, not isPercentage)
        if isPercentage then
            CfUtils.FillText(self.Txt_RankPercentage,tostring(percentageRank) .. "%")
        else
            CfUtils.FillText(self.Txt_Rank,tostring(rank))
        end
    end

    self.Txt_CombatValue.text = tostring(combatValue)
    self.Txt_Level.text = string.format("LV.%d", level)
    self.Txt_PlayerName.text = playerName
    self.LB_PlayerHead.Env:FreshAvatarFrame(avatarId, avatarFrameId)

    if not isNull(rank) and rank > 0 then
        self.SImg_Rank1.Status = rank > 4 and 4 or rank
        if not isNull(self.SImg_Rank2) then
            self.SImg_Rank2.Status = rank > 4 and 4 or rank
        end
    end



    KTool.SetActive(self.Btn_Detail, isNotNull(data.team))
end

return ActivityCrisisContractRankCell